ruleToc.chapterList:
@js:(function(){
  var j=null;
  try{j=JSON.parse(result);}catch(e){return [];}
  if(!j||!j.data)return[];
  var dd=j.data;
  var list=dd.listSong||dd.items||dd.list||[];
  var out=[];var seen={};
  for(var i=0;i<list.length;i++){
    var it=list[i]||{};
    // 无key跳过
    var k=it.key||'';if(!k||seen[k])continue;
    // 过滤 VIP: streamURL 全是 onlyVIP 或无 stream 的跳过
    var su=it.streamURL||[];
    var hasFree=false;
    for(var x=0;x<su.length;x++){if(su[x]&&!su[x].onlyVIP&&su[x].stream){hasFree=true;break;}}
    if(!hasFree&&su.length>0)continue;  // 只有VIP/无链的跳过
    seen[k]=1;
    var nm=it.name||('Track '+(i+1));
    var ar=it.artistName||'';
    var du=it.duration||0;
    var dur=du?(' ['+Math.floor(du/60)+':'+(du%60<10?'0':'')+du%60+']'):'';
    out.push({name:(i+1)+'. '+nm+(ar?' - '+ar:'')+dur,url:'https://graph.nct.vn/api/v1/song/detail/'+k});
  }
  return out;
})()
